// The rows of the details panel of the viewer of a computer for the versions of a photo (design-final 2026-10-26,
// section 4.2; design-final 2026-10-27, section 9.1, point 4): on an original, "Versions", each one with its thumbnail,
// what it is in the words of its honesty label ("3D photo, relief estimated by AI", "3D scene, reconstructed from one
// photo", "360° panorama, generated by AI beyond the photo's edges"...) and its folder, greyed with its reason on a
// drive that is not connected; on a version, "Made from salon.jpg" or "Original not found". A row opens its file the
// way a file given to the program opens (open_files.dart), even before the next scan, and has "Delete this 3D photo"
// or "Delete this version" (lot A5c), which asks first and deletes only a file that still carries our XMP with its
// DerivativeId, never the original. A 3D scene also has "Export for other 3D apps (.glb)", on its row and on its own
// "Made from" row (design-final 2026-10-27, section 8.2, point 5; scene_glb_export.dart). What they find is in
// versions.provider.dart.

import 'dart:async';
import 'dart:io';

import 'package:flutter/material.dart';
import 'package:hooks_riverpod/hooks_riverpod.dart';
import 'package:immich_mobile/desktop/ai/library/scene_glb_export.dart';
import 'package:immich_mobile/desktop/ai/library/versions.provider.dart';
import 'package:immich_mobile/desktop/ai/ui/conversions_panel.dart';
import 'package:immich_mobile/desktop/files/open_files.dart';
import 'package:immich_mobile/desktop/library/library_index.dart';
import 'package:immich_mobile/domain/models/ai_immersive/immersive_format.dart';
import 'package:immich_mobile/domain/models/asset/base_asset.model.dart';
import 'package:immich_mobile/extensions/build_context_extensions.dart';
import 'package:immich_mobile/extensions/theme_extensions.dart';
import 'package:immich_mobile/generated/translations.g.dart';
import 'package:immich_mobile/presentation/widgets/asset_viewer/sheet_tile.widget.dart';
import 'package:immich_mobile/presentation/widgets/images/thumbnail.widget.dart';
import 'package:path/path.dart' as p;

const _separator = '  •  ';

/// Opens a file of the library in the viewer; replaced in tests
final versionOpenerProvider = Provider<void Function(String path)>(
  (ref) =>
      (path) => DesktopOpenRequests.add([path]),
);

/// The versions deleted from the app in this session: the index keeps them until the next scan of their folder (up to
/// a quarter of an hour on a network folder), so their rows are left out while their files stay gone
class DeletedVersions extends Notifier<Set<String>> {
  @override
  Set<String> build() => const {};

  void add(String path) => state = {...state, path};
}

final deletedVersionsProvider = NotifierProvider<DeletedVersions, Set<String>>(DeletedVersions.new);

/// The thumbnail of a version in its row; replaced in tests
final versionThumbnailProvider = Provider<Widget Function(VersionFile file)>(
  (ref) =>
      (file) => Thumbnail.fromAsset(asset: file.asset, size: const Size.square(96)),
);

/// The versions of [asset], or the photo it was made from; nothing for a photo without either
class DesktopVersionsTiles extends ConsumerWidget {
  const DesktopVersionsTiles({super.key, required this.asset});

  final BaseAsset asset;

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final found = ref.watch(photoVersionsProvider(asset)).valueOrNull;
    if (found == null) {
      return const SizedBox.shrink();
    }
    final self = found.self;
    if (self != null) {
      return _MadeFromTile(self: self, original: found.original);
    }
    final deleted = ref.watch(deletedVersionsProvider);
    // A version made again at the same place comes back
    final versions = [
      for (final version in found.versions)
        if (!deleted.contains(version.path) || File(version.path).existsSync()) version,
    ];
    if (versions.isEmpty) {
      return const SizedBox.shrink();
    }
    return Column(
      key: const Key('desktop_versions'),
      children: [
        const SizedBox(height: 16),
        SheetTile(
          title: context.t.ai_immersive_versions,
          titleStyle: context.textTheme.labelLarge?.copyWith(color: context.colorScheme.onSurfaceSecondary),
        ),
        for (final version in versions) _VersionTile(version: version, original: asset),
      ],
    );
  }
}

/// What a version is, in the words of its honesty label: by its kind, else by its origin for a version the scan has not
/// read again since the index learnt the kinds; a version of a later format that says neither is "made by a newer
/// version"
String versionKindText(VersionFile file, Translations t) => switch (file.kind) {
  ImmersiveKind.stereoPhoto => file.isEstimatedRelief ? t.ai_immersive_3d_photo_estimated : t.ai_immersive_3d_photo,
  ImmersiveKind.volumetricScene => t.ai_immersive_version_scene,
  ImmersiveKind.panorama360 => t.ai_immersive_version_panorama,
  ImmersiveKind.stereoPanorama360 =>
    file.origin == IndexedOrigin.generated ? t.ai_immersive_version_stereo_panorama : t.ai_immersive_version_stereo_360,
  null => switch (file.origin) {
    IndexedOrigin.estimated => t.ai_immersive_3d_photo_estimated,
    IndexedOrigin.reconstructed => t.ai_immersive_version_scene,
    IndexedOrigin.generated => t.ai_immersive_version_panorama,
    IndexedOrigin.other || null => t.ai_immersive_newer_version,
  },
};

class _VersionTile extends ConsumerWidget {
  const _VersionTile({required this.version, required this.original});

  final VersionFile version;

  /// The photo whose details show it, whose versions are read again once it is deleted
  final BaseAsset original;

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final t = context.t;
    final available = version.available;
    final tile = SheetTile(
      key: ValueKey('desktop_version_${version.asset.id}'),
      title: version.name,
      titleStyle: context.textTheme.labelLarge,
      leading: ClipRRect(
        borderRadius: const BorderRadius.all(Radius.circular(4)),
        child: SizedBox.square(dimension: 48, child: ref.watch(versionThumbnailProvider)(version)),
      ),
      subtitle: [
        versionKindText(version, t),
        if (!available) t.ai_immersive_version_unavailable,
        p.dirname(version.path),
      ].join('\n'),
      subtitleStyle: context.textTheme.bodyMedium?.copyWith(color: context.colorScheme.onSurfaceSecondary),
      onTap: available ? () => ref.read(versionOpenerProvider)(version.path) : null,
      trailing: available
          ? Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                if (version.kind == ImmersiveKind.volumetricScene) _ExportGlbButton(version: version),
                IconButton(
                  key: ValueKey('desktop_version_delete_${version.asset.id}'),
                  tooltip: version.kind == ImmersiveKind.stereoPhoto
                      ? t.ai_immersive_delete_result
                      : t.ai_immersive_delete_version,
                  icon: const Icon(Icons.delete_outline_rounded),
                  onPressed: () async {
                    if (await confirmDeleteVersion(context, ref, version.path, kind: version.kind)) {
                      ref.invalidate(photoVersionsProvider(original));
                    }
                  },
                ),
              ],
            )
          : null,
    );
    return available ? tile : Opacity(opacity: 0.5, child: tile);
  }
}

class _MadeFromTile extends ConsumerWidget {
  const _MadeFromTile({required this.self, required this.original});

  final VersionFile self;
  final VersionFile? original;

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final t = context.t;
    final original = this.original;
    final titleStyle = context.textTheme.labelLarge;
    final available = original?.available ?? false;
    return Column(
      children: [
        const SizedBox(height: 16),
        SheetTile(
          key: const Key('desktop_made_from'),
          title: original == null ? t.ai_immersive_original_missing : t.ai_immersive_made_from(name: original.name),
          titleStyle: titleStyle,
          leading: Icon(Icons.view_in_ar_outlined, size: 24, color: titleStyle?.color),
          subtitle: [
            versionKindText(self, t),
            if (original != null && !available) t.ai_immersive_version_unavailable,
          ].join(_separator),
          subtitleStyle: context.textTheme.bodyMedium?.copyWith(color: context.colorScheme.onSurfaceSecondary),
          onTap: original != null && available ? () => ref.read(versionOpenerProvider)(original.path) : null,
          trailing: self.kind == ImmersiveKind.volumetricScene && self.available
              ? _ExportGlbButton(version: self)
              : null,
        ),
      ],
    );
  }
}

/// "Export for other 3D apps (.glb)" of a 3D scene
class _ExportGlbButton extends StatelessWidget {
  const _ExportGlbButton({required this.version});

  final VersionFile version;

  @override
  Widget build(BuildContext context) => IconButton(
    key: ValueKey('desktop_version_export_${version.asset.id}'),
    tooltip: context.t.ai_immersive_export_glb,
    icon: const Icon(Icons.ios_share_rounded),
    onPressed: () => unawaited(exportSceneGlb(context, version.path)),
  );
}
